let windowSize = 4h;

// S68: CI/CD Pipeline Compromise — UAVDevOps_CL엔 UAVId 없음, Target을 대리키로 사용
let S68 =
    UAVDevOps_CL
    | where TimeGenerated > ago(windowSize)
    | where UnauthorizedTrigger == true
    | extend Stage = 'S68', UAVId = tostring(Target)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S67: Registry Image Tamper — UAVDevOps_CL, DigestMismatch
let S67 =
    UAVDevOps_CL
    | where TimeGenerated > ago(windowSize)
    | where DigestMismatch == true
    | extend Stage = 'S67', UAVId = tostring(Target)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S33: Firmware Tamper — UAVPgse_CL, UAVId 보유 (TargetUAVId는 실제 컬럼 아님 — 수정)
let S33 =
    UAVPgse_CL
    | where TimeGenerated > ago(windowSize)
    | where HashMatch == false or Passed == false
    | extend Stage = 'S33', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S1: GNSS Spoofing
let S1 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'EKF_STATUS_REPORT' and PosHorizVariance > 5.0
    | extend Stage = 'S1', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S68, S67, S33, S1
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 3
| extend CampaignType = "C21_CICD침해_레지스트리변조_펌웨어_항법거부"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
